    'lang_20' => '客户将手机相机对准二维码后，它会直接转换为菜单',
    'lang_200' => '制作电子菜单的方法比您想象的要简单！观看上面的详细视频，从注册帐户到上传和发布二维码的完整教程。',
    'lang_202' => '“菜单”一词是“menu”的直译，通常用于描述餐厅菜单，所以我们说“餐厅菜单”或“餐单”。',
    'lang_203' => '如何在手机上制作歌曲二维码？',
    'lang_204' => '很遗憾，此平台专用于为餐厅、咖啡馆和商店设计二维码菜单，不支持在手机上制作歌曲二维码。',
    'lang_205' => '可以在此平台上免费制作电子菜单吗？',
    'lang_206' => '是的，可以在免费套餐或试用套餐内免费为餐厅、咖啡馆甚至商店和其他场所制作菜单，无需支付任何费用。',
    'lang_207' => '我可以编辑菜单而不影响二维码吗？',
    'lang_208' => '是的，菜单可以完全编辑而不影响二维码，并且可以在控制面板中的任何时间打印二维码。',
    'lang_209' => '可以为生产型家庭创建电子菜单吗？',
    'lang_21' => '每个菜单都有一个数字二维码，还可以通过社交媒体分享菜单链接。',
    'lang_210' => '是的，生产型家庭是核心和基础，也是提出通过 WhatsApp 转换订单这一想法的原因，以便更有效地处理订单。',
    'lang_211' => '菜单是否支持将订单转换为 WhatsApp？',
    'lang_212' => '是的，juwri 是第一个提出将订单转换为 WhatsApp 的阿拉伯平台！此功能在特定套餐中可用，请查看上面的套餐。',
    'lang_213' => '电子菜单仅适用于餐厅吗？',
    'lang_214' => '不，电子菜单适用于所有商业活动和生产型家庭，包括但不限于餐厅、咖啡馆、酒店、餐车、健康中心、美容院、展会、医院、公司和机构等。',
    'lang_215' => '我们的最新产品，菜单套餐',
