    'what_is_mcp' => '什么是 MCP？',
    'the_model_context_protocol_is_an_open_standard_that_lets_ai_agents_claude_cursor_chatgpt_and_others_call_real_tools_on_a_server_instead_of_guessing_point_a_client_at_one_of_our_five_endpoints_and_the_agent_can_browse_menus_place_orders_read_your_sales_or_validate_a_theme_against_live_brand_data' => 'Model Context Protocol 是一个开放标准，让 AI 代理（Claude、Cursor、ChatGPT 等）能够在服务器上调用真实工具，而不是凭空猜测。将客户端指向我们五个端点中的任意一个，代理即可浏览菜单、下单、读取您的销售数据，或根据 :brand 的实时数据验证主题。',
    'which_clients_can_connect' => '哪些客户端可以连接？',
    'any_mcp_capable_client_over_streamable_http_claude_code_claude_web_and_desktop_cursor_vs_code_chatgpt_developer_mode_windsurf_zed_or_raw_curl_see_the_connect_your_client_section_for_the_exact_one_command_setup_for_each' => '任何支持 MCP、通过 Streamable HTTP 连接的客户端：Claude Code、Claude（网页版和桌面版）、Cursor、VS Code、ChatGPT 开发者模式、Windsurf、Zed，或直接使用 curl。各客户端的一条命令配置方法请参见 Connect your client 部分。',
    'which_server_do_i_need' => '我需要哪个服务器？',
    'shopping_agents_use_the_public_catalog_and_storefront_servers_store_owners_use_the_admin_server_with_an_api_token_theme_and_app_developers_use_the_public_dev_server_diners_use_the_customer_server_with_their_own_login_the_which_server_do_you_need_cards_map_each_audience_to_its_server' => '购物代理使用公开的 Catalog 和 Storefront 服务器。店主使用带 API 令牌的 Admin 服务器。主题和应用开发者使用公开的 Dev 服务器。顾客使用自己登录的 Customer 服务器。"Which server do you need?" 卡片会将每类用户对应到各自的服务器。',
    'is_it_free' => '是免费的吗？',
    'connecting_is_free_the_catalog_and_dev_servers_are_fully_public_no_signup_no_key_the_admin_storefront_and_customer_servers_need_a_token_you_already_own_as_an_owner_store_or_signed_in_diner' => '连接是免费的。Catalog 和 Dev 服务器完全公开：无需注册，无需密钥。Admin、Storefront 和 Customer 服务器需要令牌，而您作为店主、店铺或已登录顾客早已拥有该令牌。',
    'do_i_need_an_api_key' => '我需要 API 密钥吗？',
    'not_for_two_of_the_five_servers_catalog_discover_restaurants_and_dev_build_themes_are_public_and_need_no_key_at_all_the_other_three_authenticate_with_a_token_you_generate_in_your_dashboard_or_receive_when_you_sign_in' => '五个服务器中有两个不需要。Catalog（发现餐厅）和 Dev（构建主题）是公开的，完全不需要密钥。其余三个服务器通过您在控制台生成或登录时获取的令牌进行身份验证。',
    'how_are_writes_protected' => '写操作如何受到保护？',
    'every_write_is_scoped_to_the_token_owner_and_audited_as_via_mcp_admin_tokens_are_ability_scoped_grant_only_what_the_agent_needs_and_tools_it_lacks_are_hidden_from_the_tool_list_entirely_keep_your_clients_human_confirmation_prompt_on_so_no_tool_runs_without_you_seeing_it' => '每次写操作都限定在令牌所有者的范围内，并以 via: mcp 的形式记录审计日志。Admin 令牌按权限范围授予：只授予代理所需的权限，代理无权使用的工具会从工具列表中完全隐藏。请保持客户端的人工确认提示开启，确保任何工具运行都不会在您不知情的情况下发生。',
    'what_are_the_rate_limits' => '速率限制是多少？',
    'each_token_is_limited_to_60_requestsminute_and_1000hour_the_storefront_server_allows_120minute_instead_bursts_beyond_that_return_http_429_back_off_and_retry' => '每个令牌限制为每分钟 60 次请求、每小时 1000 次（Storefront 服务器则允许每分钟 120 次）。超出限制的突发请求将返回 HTTP 429。请放慢速度后重试。',
    'can_i_build_my_own_theme_or_app' => '我可以自己构建主题或应用吗？',
    'yes_themes_download_the_starter_theme_build_with_the_liquid_reference_and_validate_with_the_dev_servers_validate_theme_tool_before_submitting_to_the_marketplace_apps_register_a_partner_app_for_oauth_access_webhooks_embedded_dashboard_surfaces_and_usage_billing_both_guides_live_under_developers' => '可以。主题：下载 starter theme，参照 Liquid 参考文档进行开发，并在提交到应用市场前使用 Dev 服务器的 validate_theme 工具进行验证。应用：注册合作伙伴应用以获得 OAuth 访问权限、webhooks、嵌入式控制台界面和用量计费。两份指南均位于 /developers 下。',
    'can_my_white_label_domain_use_it' => '我的白标域名可以使用它吗？',
    'yes_every_server_name_and_url_on_this_page_is_brand_aware_on_a_reseller_domain_the_endpoints_advertise_the_resellers_own_brand_and_slugged_server_names_never_the_platforms_the_discovery_manifest_at_well_knownmcpjson_is_brand_aware_too' => '可以。此页面上的每个服务器、名称和 URL 都具备品牌感知能力：在分销商域名下，端点展示的是分销商自己的品牌和相应的服务器名称，而非平台品牌。/.well-known/mcp.json 处的发现清单同样具备品牌感知能力。',
    'how_do_i_get_my_listed_data_removed' => '如何移除我被收录的数据？',
